mapper.select:
SELECT cp.position_id AS "positionId", cp.position_code AS "positionCode", cp.user_id AS "userId", ua.display_name AS "displayName",
       cp.organization_code AS "organizationCode", o.organization_name AS "organizationName",
       cp.effective_start_date AS "effectiveStartDate", cp.effective_end_date AS "effectiveEndDate", cp.use_yn AS "useYn"
FROM common_position cp
JOIN user_account ua ON ua.user_id=cp.user_id
JOIN organization o ON o.organization_code=cp.organization_code

  cp.position_id=#{f.positionId}
  AND cp.position_code=#{f.positionCode}
  AND cp.user_id=#{f.userId}
  AND cp.organization_code=#{f.organizationCode}
  AND cp.effective_start_date <= NULLIF(#{f.baseDate}, '')::date AND cp.effective_end_date >= NULLIF(#{f.baseDate}, '')::date
  AND cp.use_yn=#{f.useYn}

ORDER BY cp.position_code, cp.organization_code, cp.effective_start_date DESC

mapper.update:
UPDATE common_position SET position_code=#{body.positionCode}, user_id=#{body.userId}, organization_code=#{body.organizationCode},
  effective_start_date=NULLIF(#{body.effectiveStartDate}, '')::date, effective_end_date=NULLIF(#{body.effectiveEndDate}, '')::date,
  use_yn=COALESCE(#{body.useYn}, use_yn), updated_at=now(), change_reason=#{body.changeReason}
WHERE position_id=#{positionId}

mapper.select:
SELECT n.notice_id AS "noticeId", n.title, n.content, n.posting_start_date AS "postingStartDate", n.posting_end_date AS "postingEndDate", n.target_role_code AS "targetRoleCode", n.target_organization_code AS "targetOrganizationCode", n.important_yn AS "importantYn", n.created_by AS "createdBy", n.use_yn AS "useYn", n.created_at AS "createdAt", COUNT(a.attachment_id) AS "attachmentCount" FROM notice n LEFT JOIN notice_attachment a ON a.notice_id=n.notice_id
n.use_yn='Y' AND n.notice_id=#{f.noticeId} AND n.title LIKE CONCAT('%', #{f.title}, '%') AND n.target_role_code=#{f.targetRoleCode} AND n.target_organization_code=#{f.targetOrganizationCode} AND n.posting_start_date <= NULLIF(#{f.baseDate}, '')::date AND n.posting_end_date >= NULLIF(#{f.baseDate}, '')::date AND n.important_yn=#{f.importantYn}
GROUP BY n.notice_id ORDER BY n.important_yn DESC, n.posting_start_date DESC, n.notice_id DESC

mapper.update:
UPDATE notice SET title=#{body.title}, content=#{body.content}, posting_start_date=NULLIF(#{body.postingStartDate}, '')::date,
  posting_end_date=NULLIF(#{body.postingEndDate}, '')::date, target_role_code=NULLIF(#{body.targetRoleCode}, ''),
  target_organization_code=NULLIF(#{body.targetOrganizationCode}, ''), important_yn=COALESCE(#{body.importantYn}, important_yn),
  use_yn=COALESCE(#{body.useYn}, use_yn), updated_at=now(), change_reason=#{body.changeReason}
WHERE notice_id=#{noticeId}
